{
  "name": "opencode-quota-sidebar-plus",
  "version": "1.0.0",
  "description": "OpenCode plugin that shows quota, subscription, and token usage in TUI sidebar panels and compact session titles",
  "type": "module",
  "main": "dist/index.js",
  "types": "dist/index.d.ts",
  "exports": {
    ".": {
      "types": "./dist/index.d.ts",
      "default": "./dist/index.js"
    },
    "./tui": {
      "types": "./dist/tui.d.ts",
      "default": "./dist/tui.tsx"
    }
  },
  "oc-plugin": [
    "server",
    "tui"
  ],
  "files": [
    "dist/*.js",
    "dist/tui.tsx",
    "dist/*.d.ts",
    "dist/providers/**/*.js",
    "dist/providers/**/*.d.ts",
    "LICENSE",
    "CHANGELOG.md",
    "CONTRIBUTING.md",
    "SECURITY.md",
    "README.md",
    "README.zh-CN.md",
    "assets/OpenCode-Quota-Sidebar.png",
    "quota-sidebar.config.example.json"
  ],
  "scripts": {
    "clean": "node -e \"const fs=require('fs'); fs.rmSync('dist',{recursive:true,force:true}); fs.rmSync('tsconfig.tsbuildinfo',{force:true});\"",
    "build": "npm run clean && tsc -p tsconfig.json && node ./scripts/prepare-tui-dist.mjs",
    "prepare": "npm run build",
    "prepack": "npm run build",
    "prepublishOnly": "npm run typecheck && npm run build && npm test",
    "typecheck": "tsc -p tsconfig.json --noEmit",
    "test": "node -e \"const fs=require('fs'); const path=require('path'); const {spawnSync}=require('child_process'); const dir=path.join('dist','__tests__'); const files=fs.existsSync(dir)?fs.readdirSync(dir).filter(f=>f.endsWith('.test.js')).map(f=>path.join(dir,f)):[]; if(files.length===0){ console.error('No test files found under dist/__tests__. Run: npm run build'); process.exit(1);} const res=spawnSync(process.execPath,['--test',...files],{stdio:'inherit'}); process.exit(typeof res.status==='number'?res.status:1);\""
  },
  "keywords": [
    "opencode",
    "opencode-plugin",
    "plugin",
    "quota",
    "sidebar",
    "token-usage",
    "tui",
    "openai",
    "copilot",
    "anthropic"
  ],
  "license": "MIT",
  "author": "klj5738",
  "repository": {
    "type": "git",
    "url": "git+https://github.com/klj5738/opencode-quota-sidebar-plus.git"
  },
  "homepage": "https://github.com/klj5738/opencode-quota-sidebar-plus#readme",
  "bugs": {
    "url": "https://github.com/klj5738/opencode-quota-sidebar-plus/issues"
  },
  "publishConfig": {
    "access": "public"
  },
  "engines": {
    "node": ">=18"
  },
  "peerDependencies": {
    "@opencode-ai/plugin": "^1.3.5",
    "@opencode-ai/sdk": "^1.3.5"
  },
  "dependencies": {
    "@opentui/core": "^0.1.92",
    "@opentui/solid": "^0.1.92",
    "solid-js": "^1.9.10",
    "zod": "^4.1.8"
  },
  "devDependencies": {
    "@opencode-ai/plugin": "^1.3.5",
    "@opencode-ai/sdk": "^1.3.5",
    "@types/node": "^22.13.10",
    "typescript": "^5.8.2"
  }
}
